{
  "scenarios": [
    {
      "id": "M04-01",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我父亲去年冬天因为严重的关节炎住院了，当时他疼得下不了床，医生给他开了止痛药。我自己身体一直很好，从来没生过这种病，只是偶尔肩膀有点酸。",
          "assistant": "收到，已记录您父亲去年的住院情况以及您目前的身体状况。"
        },
        {
          "user": "补充一下，其实是我母亲在三年前做过膝盖置换手术，不是父亲。父亲只是去年冬天因为关节炎疼痛在家休养，并没有住院，之前记混了。",
          "assistant": "明白，已更正为您母亲三年前的手术史及父亲去年的居家休养情况。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "请确认一下，家里哪位长辈在三年前接受过膝关节的手术治疗？",
          "expected_facts": [
            "用户的母亲在三年前做过膝盖置换手术。"
          ],
          "required_groups": [
            ["母亲", "妈妈"],
            ["三年前", "3年前"],
            ["膝盖置换手术", "膝关节手术"]
          ]
        },
        {
          "id": "q2",
          "query": "关于父亲去年的健康状况，他是住院了还是在家休息？具体是什么问题？",
          "expected_facts": [
            "用户的父亲去年冬天因关节炎疼痛在家休养，未住院。"
          ],
          "required_groups": [
            ["父亲", "爸爸"],
            ["去年冬天", "去年冬季"],
            ["在家休养", "没住院", "居家"]
          ]
        }
      ]
    },
    {
      "id": "M04-02",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我弟弟上个月被诊断出患有哮喘，现在需要每天使用吸入器。我自己虽然小时候有过过敏，但成年后完全好了，最近也没有任何呼吸方面的问题。",
          "assistant": "好的，已记录您弟弟上个月的诊断结果及您过去的过敏史。"
        },
        {
          "user": "不对，刚才说错了，是妹妹上个月确诊的哮喘，弟弟其实很健康。至于我自己，小时候确实有季节性过敏，但那是很久以前的事了，现在没问题。",
          "assistant": "收到，已更新为您妹妹的确诊信息，并保留您儿时的过敏记录。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "家里谁在上个月被确诊为哮喘并开始使用吸入器治疗？",
          "expected_facts": [
            "用户的妹妹在上个月被诊断出患有哮喘。"
          ],
          "required_groups": [
            ["妹妹", "小妹"],
            ["上个月", "上月"],
            ["哮喘", "气喘"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人是否有过呼吸系统相关的病史，目前状态如何？",
          "expected_facts": [
            "用户小时候有过季节性过敏，但成年后已痊愈，目前无呼吸问题。"
          ],
          "required_groups": [
            ["小时候", "儿时", "幼年"],
            ["季节性过敏", "过敏"],
            ["已痊愈", "好了", "没问题"]
          ]
        }
      ]
    },
    {
      "id": "M04-03",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我的丈夫两年前因为高血压开始服药控制，最近血压稳定了。我自己体检时血糖稍微偏高，医生建议我注意饮食，但我没有糖尿病，只是处于临界状态。",
          "assistant": "了解，已记录您丈夫的高血压病史及您目前的血糖状况。"
        },
        {
          "user": "更正一下，是妻子两年前确诊高血压，不是丈夫。丈夫身体一直很棒。我自己确实是血糖偏高，但从未被诊断为糖尿病，只是需要注意生活方式。",
          "assistant": "明白，已修正为您妻子的病史，并确认您目前的血糖临界状态。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "请问您的配偶中，谁在两年前被确诊为高血压并开始服药？",
          "expected_facts": [
            "用户的妻子在两年前确诊高血压并开始服药。"
          ],
          "required_groups": [
            ["妻子", "老婆"],
            ["两年前", "2年前"],
            ["高血压", "血压高"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人的血糖情况如何，是否已经确诊为糖尿病？",
          "expected_facts": [
            "用户体检发现血糖偏高，但未确诊糖尿病，处于临界状态。"
          ],
          "required_groups": [
            ["血糖偏高", "血糖高"],
            ["未确诊", "没有糖尿病"],
            ["临界状态", "注意饮食"]
          ]
        }
      ]
    },
    {
      "id": "M04-04",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我姐姐五年前因为甲状腺结节做了切除手术，恢复得很好。我自己去年体检时发现也有一个小结节，医生说观察即可，不需要手术，我也没吃药。",
          "assistant": "好的，已记录您姐姐的手术史和您去年的体检发现。"
        },
        {
          "user": "抱歉记错了，是哥哥五年前做的甲状腺手术，姐姐很健康。我自己去年的确发现了结节，医生建议定期复查，目前没有任何不适症状。",
          "assistant": "收到，已更正为您哥哥的手术记录，并确认您目前的观察方案。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "家里哪位亲属在五年前接受了甲状腺相关的手术治疗？",
          "expected_facts": [
            "用户的哥哥在五年前做了甲状腺结节切除手术。"
          ],
          "required_groups": [
            ["哥哥", "大哥"],
            ["五年前", "5年前"],
            ["甲状腺手术", "切除手术"]
          ]
        },
        {
          "id": "q2",
          "query": "用户去年体检发现的甲状腺问题，目前采取了什么处理措施？",
          "expected_facts": [
            "用户去年发现甲状腺结节，医生建议观察，无需手术或服药。"
          ],
          "required_groups": [
            ["去年", "去年体检"],
            ["观察", "定期复查"],
            ["无需手术", "没吃药"]
          ]
        }
      ]
    },
    {
      "id": "M04-05",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我女儿去年夏天因为食物中毒住了一天院，后来就好了。我自己肠胃一直比较弱，经常拉肚子，但从来没有因为这个问题住过医院。",
          "assistant": "明白，已记录您女儿的住院经历及您长期的肠胃状况。"
        },
        {
          "user": "不对，是儿子去年夏天食物中毒住院的，女儿没事。我自己确实肠胃不好，容易腹泻，但从未因此入院治疗，都是在家调理。",
          "assistant": "收到，已更正为您儿子的住院记录，并确认您在家调理的情况。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "您的孩子中，谁在去年夏天因食物中毒而住院治疗？",
          "expected_facts": [
            "用户的儿子在去年夏天因食物中毒住院一天。"
          ],
          "required_groups": [
            ["儿子", "孩子"],
            ["去年夏天", "去年夏季"],
            ["食物中毒", "吃坏肚子"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人是否有过因肠胃问题住院的历史？平时如何处理？",
          "expected_facts": [
            "用户肠胃较弱常腹泻，但从未住院，均在家调理。"
          ],
          "required_groups": [
            ["肠胃弱", "拉肚子"],
            ["从未住院", "没住过院"],
            ["在家调理", "自己处理"]
          ]
        }
      ]
    },
    {
      "id": "M04-06",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我婆婆三年前因为白内障做了激光手术，视力恢复不错。我自己眼睛度数很深，戴眼镜很多年了，但从未做过眼部手术，也没得过白内障。",
          "assistant": "好的，已记录您婆婆的手术史及您的视力矫正情况。"
        },
        {
          "user": "更正一下，是公公三年前做的白内障手术，婆婆眼睛很好。我自己确实高度近视，长期佩戴眼镜，但从未进行过眼部手术。",
          "assistant": "明白，已更新为您公公的手术记录，并确认您的近视状况。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "您的公婆中，谁在三年前接受了白内障激光手术治疗？",
          "expected_facts": [
            "用户的公公在三年前做了白内障激光手术。"
          ],
          "required_groups": [
            ["公公", "岳父"],
            ["三年前", "3年前"],
            ["白内障手术", "激光手术"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人的视力问题是什么，是否做过眼部手术？",
          "expected_facts": [
            "用户高度近视长期戴眼镜，从未做过眼部手术。"
          ],
          "required_groups": [
            ["高度近视", "度数深"],
            ["戴眼镜", "佩戴眼镜"],
            ["从未手术", "没做过手术"]
          ]
        }
      ]
    },
    {
      "id": "M04-07",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我侄子四年前因为骨折打了石膏，修养了一个月。我自己运动时扭伤过脚踝，贴了膏药就好，从来没断过骨头，也不需要打石膏。",
          "assistant": "收到，已记录您侄子的骨折史及您过往的扭伤经历。"
        },
        {
          "user": "抱歉，是外甥四年前骨折打的石膏，侄子没事。我自己确实扭伤过脚踝，只是软组织损伤，从未骨折，更没打过石膏。",
          "assistant": "明白，已更正为您外甥的骨折记录，并确认您仅为扭伤。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "您的晚辈中，谁在四年前因骨折而使用了石膏固定？",
          "expected_facts": [
            "用户的外甥在四年前因骨折打了石膏。"
          ],
          "required_groups": [
            ["外甥", "侄子"],
            ["四年前", "4年前"],
            ["骨折", "断骨"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人是否有过骨折经历，之前的脚部受伤是如何处理的？",
          "expected_facts": [
            "用户曾扭伤脚踝，属软组织损伤，未骨折也未打石膏。"
          ],
          "required_groups": [
            ["扭伤", "脚部受伤"],
            ["未骨折", "没断骨"],
            ["贴膏药", "软组织损伤"]
          ]
        }
      ]
    },
    {
      "id": "M04-08",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我表姐两年前因为抑郁症休学了半年，后来复学并好转。我自己工作压力大时会有焦虑情绪，但从未达到抑郁程度，也没休学过。",
          "assistant": "好的，已记录您表姐的休学经历及您的压力反应。"
        },
        {
          "user": "更正一下，是表哥两年前因抑郁症休学的，表姐很健康。我自己确实有焦虑情绪，但从未确诊抑郁症，也从未因此休学。",
          "assistant": "收到，已更新为您表哥的病史，并确认您目前的心理状态。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "您的表亲中，谁在两年前因心理健康问题休学了半年？",
          "expected_facts": [
            "用户的表哥在两年前因抑郁症休学半年。"
          ],
          "required_groups": [
            ["表哥", "表姐"],
            ["两年前", "2年前"],
            ["抑郁症", "心理问题"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人是否有过抑郁症诊断或因此休学的经历？",
          "expected_facts": [
            "用户有焦虑情绪，但未确诊抑郁症，从未休学。"
          ],
          "required_groups": [
            ["焦虑情绪", "压力大"],
            ["未确诊", "没得抑郁症"],
            ["从未休学", "没休学"]
          ]
        }
      ]
    },
    {
      "id": "M04-09",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我邻居老张去年因为心脏病突发去世了，这让我很震惊。我自己心脏一直很好，每年体检都正常，没有任何心脏方面的疾病史。",
          "assistant": "理解，已记录您邻居的情况及您健康的体检结果。"
        },
        {
          "user": "不对，是老李去年心脏病去世的，老张还在世。我自己确实心脏健康，历年体检指标均正常，从未患过心脏病。",
          "assistant": "明白，已更正为您邻居老李的离世记录，并确认您的心脏健康状况。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "您提到的邻居中，谁在去年因心脏病突发去世？",
          "expected_facts": [
            "用户的邻居老李在去年因心脏病突发去世。"
          ],
          "required_groups": [
            ["老李", "邻居"],
            ["去年", "去年"],
            ["心脏病", "心脏突发"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人的心脏健康状况如何，是否有相关病史？",
          "expected_facts": [
            "用户心脏健康，历年体检正常，无心脏病史。"
          ],
          "required_groups": [
            ["心脏健康", "心脏好"],
            ["体检正常", "指标正常"],
            ["无病史", "没得过"]
          ]
        }
      ]
    },
    {
      "id": "M04-10",
      "category": "用户和家人的经历区分",
      "turns": [
        {
          "user": "我同事小王上个月因为流感发烧请假了一周，现在已经康复返岗。我自己免疫力很强，很少生病，去年冬天也没感冒过，一直全勤。",
          "assistant": "好的，已记录您同事的病假情况及您良好的出勤记录。"
        },
        {
          "user": "更正一下，是小李上个月因流感请假的，小王很健康。我自己确实很少生病，去年冬天全程未感冒，保持了全勤。",
          "assistant": "收到，已更新为您同事小李的病假记录，并确认您的全勤状态。"
        }
      ],
      "queries": [
        {
          "id": "q1",
          "query": "您的同事中，谁在上个月因流感发烧而请假一周？",
          "expected_facts": [
            "用户的同事小李在上个月因流感发烧请假一周。"
          ],
          "required_groups": [
            ["小李", "同事"],
            ["上个月", "上月"],
            ["流感", "发烧"]
          ]
        },
        {
          "id": "q2",
          "query": "用户本人在去年冬天的健康状况如何，是否有请假记录？",
          "expected_facts": [
            "用户去年冬天未感冒，保持全勤，无请假记录。"
          ],
          "required_groups": [
            ["去年冬天", "去年冬季"],
            ["未感冒", "没生病"],
            ["全勤", "没请假"]
          ]
        }
      ]
    }
  ]
}
